mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, c1.C_Name as ptContractorName, c1.C_Abbreviation as ptContractorAbbName, c2.C_Name as ptSupervisorName, c2.C_Abbreviation as ptSupervisorAbbName, c3.C_Name as ptEvaluationUnitName, c3.C_Abbreviation as ptEvaluationUnitAbbName, c4.C_Name as ptRectifyName, c4.C_Abbreviation as ptRectifyAbbName, u1.U_Name as ptPmName, u2.U_Name as ptCseName, qp.Qsp_Code as qspCode, qp.Qsp_Name as qspName, ,
from Qs_PT_Spot_Check mn left join Qs_Plan_Task qpt on mn.pt_id=qpt.id left join Qs_Plan qp on qp.Qsp_Id=qpt.Qsp_Id left join Pre_Project pro on pro.P_Id=qpt.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Company pAgentc on pAgentc.C_Id=pro.P_Agent_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Con_Contract con on con.Con_Id = qpt.Con_Id left join SYS_Company c1 on c1.C_Id = qpt.Pt_Contractor_Id left join SYS_Company c2 on c2.C_Id = qpt.Pt_Supervisor_Id left join SYS_Company c3 on c3.C_Id = qpt.Pt_Evaluation_Unit_Id left join SYS_Company c4 on c4.C_Id = qpt.Pt_Rectify_Cid left join Sys_User u1 on u1.U_Id = qpt.Pt_Pm left join Sys_User u2 on u2.U_Id = qpt.Pt_Cse
${params.authSql}
where 1=1
and mn.Te_Id = #{params.teId}
and qpt.Pt_Type=#{params.ptType}
and qpt.Pt_Category=#{params.ptCategory}
and mn.State=#{params.state}
and qpt.P_Id=#{params.pId}
and qpt.Pt_Measure=#{params.ptMeasure}
and qpt.Pt_Is_Construction=#{params.ptIsConstruction}
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(qpt.Pt_Code,#{params.ptCode})
and INSTR(qpt.Pt_Group_Leader_Name,#{params.ptGroupLeaderName})
and INSTR(qpt.Pt_Team_Leader_Name,#{params.ptTeamLeaderName})
and INSTR(qpt.Pt_Group_Member_Name,#{params.ptGroupMemberName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(con.Con_Name,#{params.conName})
and INSTR(u1.U_Name,#{params.ptPmName})
and INSTR(u2.U_Name,#{params.ptCseName})
and likeCname(#{params.ptContractorName},c1.C_Id)=true
and INSTR(c1.C_Name,#{params.ptContractorName})
and likeCname(#{params.ptSupervisorName},c2.C_Id)=true
and INSTR(c2.C_Name,#{params.ptSupervisorName})
and likeCname(#{params.ptRectifyName},c4.C_Id)=true
and INSTR(c4.C_Name,#{params.ptRectifyName})
and to_char(qpt.Pt_Evaluation_Time,'yyyy-MM-dd') >= #{params.ptEvaluationTimeStart}
and to_char(qpt.Pt_Evaluation_Time,'yyyy-MM-dd') <= #{params.ptEvaluationTimeEnd}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
